export { BlSelect } from './select.js';
export { BlOption } from './option.js';
export { BlOptionGroup } from './option-group.js';
export type { SelectSize } from './select.js';

import { css } from 'lit';

export const optionGroupStyles = css`
  :host {
    display: block;
  }

  .group-label {
    padding: var(--bl-spacing-sm) var(--bl-spacing-sm) var(--bl-spacing-xs);
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-xs);
    font-weight: 600;
    color: var(--bl-color-neutral-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    user-select: none;
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { optionGroupStyles } from './option-group.styles.js';

/**
 * A labelled group of options within a `bl-select`.
 *
 * @element bl-option-group
 * @slot - `bl-option` elements.
 */
@customElement('bl-option-group')
export class BlOptionGroup extends LitElement {
  static override styles = [tokens, optionGroupStyles];

  /** The group label. */
  @property()
  label = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'group');
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('label')) {
      this.setAttribute('aria-label', this.label);
    }
  }

  protected override render() {
    return html`
      <div class="group-label" aria-hidden="true">${this.label}</div>
      <slot></slot>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-option-group': BlOptionGroup;
  }
}

import { css } from 'lit';

export const optionStyles = css`
  :host {
    display: block;
  }

  :host([aria-disabled='true']) {
    pointer-events: none;
    opacity: 0.5;
  }

  .option {
    display: flex;
    align-items: center;
    gap: var(--bl-spacing-sm);
    padding: var(--bl-spacing-xs) var(--bl-spacing-sm);
    cursor: pointer;
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-800);
    border-radius: var(--bl-radius-sm);
    transition: background-color var(--bl-transition-fast);
    user-select: none;
  }

  .option:hover,
  :host([data-highlighted]) .option {
    background-color: var(--bl-color-neutral-100);
  }

  :host([aria-selected='true']) .option {
    color: var(--bl-color-primary-700);
    font-weight: 500;
  }

  .check {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    opacity: 0;
  }

  :host([aria-selected='true']) .check {
    opacity: 1;
    color: var(--bl-color-primary-600);
  }
`;

import { LitElement, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { optionStyles } from './option.styles.js';

/**
 * An option within a `bl-select`.
 *
 * @element bl-option
 * @slot - Option label text.
 * @csspart option - The option container.
 */
@customElement('bl-option')
export class BlOption extends LitElement {
  static override styles = [tokens, optionStyles];

  private _optionId = `bl-opt-${Math.random().toString(36).slice(2, 9)}`;

  /** The value this option represents. */
  @property()
  value = '';

  /** Whether this option is disabled. */
  @property({ type: Boolean })
  disabled = false;

  override connectedCallback(): void {
    super.connectedCallback();
    this.setAttribute('role', 'option');
    this.id = this.id || this._optionId;
    this.addEventListener('click', this._handleClick);
    this.addEventListener('mouseenter', this._handleMouseEnter);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('click', this._handleClick);
    this.removeEventListener('mouseenter', this._handleMouseEnter);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('disabled')) {
      this.setAttribute('aria-disabled', String(this.disabled));
    }
  }

  /** Get the display text of this option. */
  getLabel(): string {
    return (this.textContent ?? '').trim();
  }

  /** Set the highlighted (hover) state. */
  setHighlighted(highlighted: boolean): void {
    if (highlighted) {
      this.setAttribute('data-highlighted', '');
    } else {
      this.removeAttribute('data-highlighted');
    }
  }

  /** Set the selected state. */
  setSelected(selected: boolean): void {
    this.setAttribute('aria-selected', String(selected));
  }

  private _handleClick = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-option-select', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  private _handleMouseEnter = (): void => {
    if (this.disabled) return;
    this.dispatchEvent(
      new CustomEvent('bl-option-highlight', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  };

  protected override render() {
    return html`
      <div class="option" part="option">
        <svg
          class="check"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2.5"
          stroke-linecap="round"
          stroke-linejoin="round"
          aria-hidden="true"
        >
          <polyline points="20 6 9 17 4 12"></polyline>
        </svg>
        <slot></slot>
      </div>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-option': BlOption;
  }
}

import { css } from 'lit';

export const selectStyles = css`
  :host {
    display: inline-block;
    position: relative;
    min-width: 180px;
  }

  :host([disabled]) {
    opacity: 0.5;
    pointer-events: none;
  }

  .trigger {
    display: flex;
    align-items: center;
    justify-content: space-between;
    width: 100%;
    gap: var(--bl-spacing-sm);
    padding: var(--bl-spacing-sm) var(--bl-spacing-md);
    background-color: #fff;
    border: 1px solid var(--bl-color-neutral-300);
    border-radius: var(--bl-radius-md);
    cursor: pointer;
    font-family: var(--bl-font-family-base);
    font-size: var(--bl-font-size-sm);
    color: var(--bl-color-neutral-900);
    box-shadow: var(--bl-shadow-xs);
    transition:
      border-color var(--bl-transition-fast),
      box-shadow var(--bl-transition-fast);
  }

  .trigger:hover {
    border-color: var(--bl-color-neutral-400);
  }

  .trigger:focus-visible {
    outline: 2px solid var(--bl-focus-ring-color);
    outline-offset: 2px;
  }

  :host([open]) .trigger {
    border-color: var(--bl-color-primary-500);
    box-shadow: 0 0 0 1px var(--bl-color-primary-500);
  }

  .trigger-text {
    flex: 1;
    text-align: left;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .trigger-text.placeholder {
    color: var(--bl-color-neutral-400);
  }

  .trigger-icon {
    width: 16px;
    height: 16px;
    flex-shrink: 0;
    color: var(--bl-color-neutral-500);
    transition: transform var(--bl-transition-fast);
  }

  :host([open]) .trigger-icon {
    transform: rotate(180deg);
  }

  /* Sizes */
  :host([size='sm']) .trigger {
    padding: var(--bl-spacing-xs) var(--bl-spacing-sm);
    font-size: var(--bl-font-size-xs);
    min-height: 1.75rem;
  }

  :host([size='lg']) .trigger {
    padding: var(--bl-spacing-sm) var(--bl-spacing-lg);
    font-size: var(--bl-font-size-md);
    min-height: 2.75rem;
  }

  .listbox {
    position: fixed;
    z-index: var(--bl-z-dropdown);
    min-width: 100%;
    max-height: 240px;
    overflow-y: auto;
    padding: var(--bl-spacing-xs);
    background-color: #fff;
    border: 1px solid var(--bl-color-neutral-200);
    border-radius: var(--bl-radius-md);
    box-shadow: var(--bl-shadow-lg);

    opacity: 0;
    transform: translateY(4px);
    transition:
      opacity var(--bl-animation-duration-fast) var(--bl-animation-easing-enter),
      transform var(--bl-animation-duration-fast) var(--bl-animation-easing-enter);
  }

  .listbox[data-state='entering'],
  .listbox[data-state='entered'] {
    opacity: 1;
    transform: translateY(0);
  }

  .listbox[data-state='exiting'] {
    opacity: 0;
    transform: translateY(4px);
    transition:
      opacity var(--bl-animation-duration-fast) var(--bl-animation-easing-exit),
      transform var(--bl-animation-duration-fast) var(--bl-animation-easing-exit);
  }

  /* Hidden native select for form submission */
  .native-select {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
  }
`;

import { LitElement, html, nothing } from 'lit';
import { customElement, property, state } from 'lit/decorators.js';
import { tokens } from '../../styles/tokens.js';
import { selectStyles } from './select.styles.js';
import { OverlayController } from '../controllers/overlay.js';
import { AnimationController } from '../controllers/animation.js';
import { ClickOutsideController } from '../controllers/click-outside.js';
import { TypeaheadController } from '../controllers/typeahead.js';
import type { BlOption } from './option.js';
import type { Placement } from '@floating-ui/dom';

export type SelectSize = 'sm' | 'md' | 'lg';

/**
 * A select dropdown with virtual focus (aria-activedescendant).
 *
 * @element bl-select
 * @slot - `bl-option` and `bl-option-group` elements.
 * @fires bl-change - Emitted when the selected value changes.
 */
@customElement('bl-select')
export class BlSelect extends LitElement {
  static override styles = [tokens, selectStyles];

  private _overlay = new OverlayController(this, { matchWidth: true });
  private _animation = new AnimationController(this, { enterDuration: 150, exitDuration: 100 });
  private _clickOutside = new ClickOutsideController(this, {
    onClickOutside: () => { if (this.open) this._close(); },
    active: false,
  });
  private _typeahead = new TypeaheadController(this, {
    selector: 'bl-option:not([aria-disabled="true"])',
    onMatch: (_item, index) => this._highlightIndex(index),
  });

  private _listboxId = `bl-select-lb-${Math.random().toString(36).slice(2, 9)}`;
  private _highlightedIndex = -1;

  /** The selected value. */
  @property()
  value = '';

  /** Form name for hidden select. */
  @property()
  name = '';

  /** Placeholder text when no value is selected. */
  @property()
  placeholder = 'Select an option';

  /** Whether the select is open. */
  @property({ type: Boolean, reflect: true })
  open = false;

  /** Whether the select is disabled. */
  @property({ type: Boolean, reflect: true })
  disabled = false;

  /** Size variant. */
  @property({ reflect: true })
  size: SelectSize = 'md';

  /** Preferred placement. */
  @property()
  placement: Placement = 'bottom-start';

  @state()
  private _visible = false;

  @state()
  private _displayText = '';

  override connectedCallback(): void {
    super.connectedCallback();
    this.addEventListener('keydown', this._handleKeyDown);
    this.addEventListener('bl-option-select', this._handleOptionSelect as EventListener);
    this.addEventListener('bl-option-highlight', this._handleOptionHighlight as EventListener);
  }

  override disconnectedCallback(): void {
    super.disconnectedCallback();
    this.removeEventListener('keydown', this._handleKeyDown);
    this.removeEventListener('bl-option-select', this._handleOptionSelect as EventListener);
    this.removeEventListener('bl-option-highlight', this._handleOptionHighlight as EventListener);
  }

  override updated(changed: Map<string, unknown>): void {
    if (changed.has('open')) {
      if (this.open) {
        this._openListbox();
      } else if (this._visible) {
        this._closeListbox();
      }
    }
    if (changed.has('value')) {
      this._syncSelection();
    }
  }

  private _getOptions(): BlOption[] {
    return Array.from(this.querySelectorAll<BlOption>('bl-option'));
  }

  private _syncSelection(): void {
    const options = this._getOptions();
    options.forEach((opt) => opt.setSelected(opt.value === this.value));
    const selected = options.find((opt) => opt.value === this.value);
    this._displayText = selected?.getLabel() ?? '';
  }

  private _handleTriggerClick = (): void => {
    if (this.disabled) return;
    if (this.open) {
      this._close();
    } else {
      this.open = true;
    }
  };

  private _handleKeyDown = (e: KeyboardEvent): void => {
    if (this.disabled) return;

    if (!this.open) {
      if (e.key === 'Enter' || e.key === ' ' || e.key === 'ArrowDown' || e.key === 'ArrowUp') {
        e.preventDefault();
        this.open = true;
        return;
      }
    }

    const options = this._getOptions().filter((o) => !o.disabled);
    if (options.length === 0) return;

    if (e.key === 'ArrowDown') {
      e.preventDefault();
      this._highlightIndex(
        this._highlightedIndex + 1 >= options.length ? 0 : this._highlightedIndex + 1,
      );
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      this._highlightIndex(
        this._highlightedIndex - 1 < 0 ? options.length - 1 : this._highlightedIndex - 1,
      );
    } else if (e.key === 'Home') {
      e.preventDefault();
      this._highlightIndex(0);
    } else if (e.key === 'End') {
      e.preventDefault();
      this._highlightIndex(options.length - 1);
    } else if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (this._highlightedIndex >= 0 && this._highlightedIndex < options.length) {
        this._selectOption(options[this._highlightedIndex]!.value);
      }
    } else if (e.key === 'Escape') {
      e.preventDefault();
      this._close();
    } else if (e.key === 'Tab') {
      this._close();
    }
  };

  private _highlightIndex(index: number): void {
    const options = this._getOptions().filter((o) => !o.disabled);
    options.forEach((opt) => opt.setHighlighted(false));

    if (index >= 0 && index < options.length) {
      this._highlightedIndex = index;
      options[index]!.setHighlighted(true);
      // Virtual focus: update aria-activedescendant
      const trigger = this.shadowRoot!.querySelector<HTMLElement>('.trigger');
      trigger?.setAttribute('aria-activedescendant', options[index]!.id);
      options[index]!.scrollIntoView({ block: 'nearest' });
    }
  }

  private _handleOptionSelect = (e: CustomEvent<{ value: string }>): void => {
    e.stopPropagation();
    this._selectOption(e.detail.value);
  };

  private _handleOptionHighlight = (e: CustomEvent<{ value: string }>): void => {
    e.stopPropagation();
    const options = this._getOptions().filter((o) => !o.disabled);
    const idx = options.findIndex((opt) => opt.value === e.detail.value);
    if (idx !== -1) this._highlightIndex(idx);
  };

  private _selectOption(value: string): void {
    this.value = value;
    this._syncSelection();
    this._close();
    this.dispatchEvent(
      new CustomEvent('bl-change', {
        detail: { value: this.value },
        composed: true,
        bubbles: true,
      }),
    );
  }

  private async _openListbox(): Promise<void> {
    if (this._visible) return;
    this._visible = true;
    await this.updateComplete;

    const trigger = this.shadowRoot!.querySelector<HTMLElement>('.trigger');
    const listbox = this.shadowRoot!.querySelector<HTMLElement>('.listbox');
    if (!trigger || !listbox) return;

    this._overlay.setPlacement(this.placement);
    this._overlay.show(trigger, listbox);
    this._animation.enter(listbox);
    this._clickOutside.active = true;

    // Highlight selected option
    const options = this._getOptions().filter((o) => !o.disabled);
    const selectedIdx = options.findIndex((opt) => opt.value === this.value);
    this._highlightIndex(selectedIdx >= 0 ? selectedIdx : 0);
  }

  private async _closeListbox(): Promise<void> {
    if (!this._visible) return;

    const listbox = this.shadowRoot!.querySelector<HTMLElement>('.listbox');
    if (listbox) {
      await this._animation.exit(listbox);
    }

    this._overlay.hide();
    this._clickOutside.active = false;
    this._visible = false;
    this._highlightedIndex = -1;

    const trigger = this.shadowRoot!.querySelector<HTMLElement>('.trigger');
    trigger?.removeAttribute('aria-activedescendant');
    trigger?.focus();
  }

  private _close(): void {
    this.open = false;
  }

  protected override render() {
    const hasValue = this._displayText !== '';

    return html`
      <button
        class="trigger"
        part="trigger"
        type="button"
        role="combobox"
        aria-haspopup="listbox"
        aria-expanded=${this.open ? 'true' : 'false'}
        aria-controls=${this._visible ? this._listboxId : nothing}
        aria-disabled=${this.disabled ? 'true' : 'false'}
        @click=${this._handleTriggerClick}
      >
        <span class="trigger-text ${hasValue ? '' : 'placeholder'}">
          ${hasValue ? this._displayText : this.placeholder}
        </span>
        <svg
          class="trigger-icon"
          viewBox="0 0 24 24"
          fill="none"
          stroke="currentColor"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
          aria-hidden="true"
        >
          <polyline points="6 9 12 15 18 9"></polyline>
        </svg>
      </button>

      ${this._visible
        ? html`
            <div
              class="listbox"
              id=${this._listboxId}
              role="listbox"
            >
              <slot @slotchange=${this._syncSelection}></slot>
            </div>
          `
        : nothing}

      ${this.name
        ? html`<select class="native-select" tabindex="-1" aria-hidden="true" .value=${this.value}>
            <option value=${this.value}>${this._displayText}</option>
          </select>`
        : nothing}
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'bl-select': BlSelect;
  }
}
